class Command:
    """An edit reified as an object: it knows how to apply itself and how to
    take itself back, and it stores whatever it needs to do the latter."""

    name = ""

    def execute(self, doc: str) -> str:
        raise NotImplementedError

    def undo(self, doc: str) -> str:
        raise NotImplementedError


class Append(Command):
    name = "append"

    def __init__(self, text: str):
        self.text = text

    def execute(self, doc: str) -> str:
        return doc + self.text

    def undo(self, doc: str) -> str:
        return doc[: len(doc) - len(self.text)]


class Delete(Command):
    name = "delete"

    def __init__(self, k: int):
        self.k = k
        self.removed = ""  # captured at execute time, so undo can put it back

    def execute(self, doc: str) -> str:
        cut = min(self.k, len(doc))
        self.removed = doc[len(doc) - cut:]
        return doc[: len(doc) - cut]

    def undo(self, doc: str) -> str:
        return doc + self.removed


class Editor:
    def __init__(self):
        self.doc = ""
        self.undo_stack = []
        self.redo_stack = []

    def _run(self, command: Command) -> str:
        self.doc = command.execute(self.doc)
        self.undo_stack.append(command)
        self.redo_stack.clear()
        return self.doc

    def append(self, text: str) -> str:
        return self._run(Append(text))

    def delete(self, k: int) -> str:
        return self._run(Delete(k))

    def undo(self) -> str:
        if not self.undo_stack:
            return self.doc
        command = self.undo_stack.pop()
        self.doc = command.undo(self.doc)
        self.redo_stack.append(command)
        return self.doc

    def redo(self) -> str:
        if not self.redo_stack:
            return self.doc
        command = self.redo_stack.pop()
        self.doc = command.execute(self.doc)
        self.undo_stack.append(command)
        return self.doc

    def history(self) -> list[str]:
        return [command.name for command in self.undo_stack]
